#include <torch/extension.h>
torch::Tensor max_reduce(torch::Tensor x, int64_t dim);
"""

max_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
#include <math.h>
#include <vector>
#include <cstdint>
#include <algorithm>

using namespace cute;

template <int Threads, int TileI, int ChunkR>
__global__ void max_reduce_dim_kernel(const float* __restrict__ X,
                                      float* __restrict__ Y,
                                      int outer,
                                      int R,
                                      int inner)
{
  constexpr int RowStride = TileI + 4;
  __shared__ __align__(16) float s[ChunkR][RowStride];
  __shared__ int s_pad[ChunkR];
  const int o = blockIdx.z + blockIdx.y * gridDim.z;
  if (o >= outer) return;
  const int i_base = blockIdx.x * TileI;
  if (i_base >= inner) return;
  const int tile = min(TileI, inner - i_base);
  const int tid = threadIdx.x;
  const float* x_base = X + (int64_t)o * (int64_t)R * (int64_t)inner;
  constexpr int kPerThread = TileI / Threads;
  float acc[kPerThread];
  #pragma unroll
  for (int k = 0; k < kPerThread; ++k) acc[k] = -INFINITY;
  for (int r_base = 0; r_base < R; r_base += ChunkR) {
    const int rows = min(ChunkR, R - r_base);
    // Stage a ChunkR x TileI tile into shared memory using 16-byte
    // vectorized global loads. Row start alignment varies with r because
    // inner is odd, so each row is shifted in smem by pad such that the
    // float4 body is always 16B aligned in both gmem and smem.
    for (int lr = 0; lr < rows; ++lr) {
      const float* row = x_base + (int64_t)(r_base + lr) * (int64_t)inner + i_base;
      const uintptr_t addr = reinterpret_cast<uintptr_t>(row);
      int head = (int)(((16 - (addr & 15)) & 15) >> 2);
      if (head > tile) head = tile;
      const int pad = (4 - head) & 3;
      if (tid == 0) s_pad[lr] = pad;
      float* srow = &s[lr][0];
      if (tid < head) srow[pad + tid] = row[tid];
      const int nvec = (tile - head) >> 2;
      const float4* row4 = reinterpret_cast<const float4*>(row + head);
      float4* srow4 = reinterpret_cast<float4*>(srow + pad + head);
      for (int v = tid; v < nvec; v += Threads) {
        srow4[v] = row4[v];
      }
      const int tail0 = head + (nvec << 2);
      if (tid < tile - tail0) srow[pad + tail0 + tid] = row[tail0 + tid];
    }
    __syncthreads();
    // Reduce the staged tile from shared memory (conflict-free scalar reads).
    for (int lr = 0; lr < rows; ++lr) {
      const float* srow = &s[lr][s_pad[lr]];
      #pragma unroll
      for (int k = 0; k < kPerThread; ++k) {
        const int j = tid + k * Threads;
        if (j < tile) acc[k] = fmaxf(acc[k], srow[j]);
      }
    }
    __syncthreads();
  }
  float* y_base = Y + (int64_t)o * (int64_t)inner;
  Tensor mY = make_tensor(make_gmem_ptr(y_base),
                          make_shape(inner),
                          make_stride(Int<1>{}));
  #pragma unroll
  for (int k = 0; k < kPerThread; ++k) {
    const int j = tid + k * Threads;
    if (j < tile) mY(i_base + j) = acc[k];
  }
}
torch::Tensor max_reduce(torch::Tensor x, int64_t dim)
{
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(x.dim() >= 1, "x must have at least 1 dimension");
  auto x_c = x.contiguous();
  int64_t nd = x_c.dim();
  if (dim < 0) dim += nd;
  TORCH_CHECK(dim >= 0 && dim < nd, "dim out of range");
  int64_t outer = 1;
  for (int64_t d = 0; d < dim; ++d) outer *= x_c.size(d);
  int64_t R = x_c.size(dim);
  int64_t inner = 1;
  for (int64_t d = dim + 1; d < nd; ++d) inner *= x_c.size(d);
  std::vector<int64_t> out_sizes;
  out_sizes.reserve(nd - 1);
  for (int64_t d = 0; d < nd; ++d) {
    if (d != dim) out_sizes.push_back(x_c.size(d));
  }
  auto y = torch::empty(out_sizes, x_c.options());
  if (outer == 0 || inner == 0) return y;
