  constexpr int TileI = 512;
  constexpr int ChunkR = 8;
  const int64_t max_z = 65535;
  const int64_t outer_chunks = (outer + max_z - 1) / max_z;
  const int64_t outer_per_chunk = std::min<int64_t>(outer, max_z);
  const int64_t inner_blocks = (inner + TileI - 1) / TileI;
  dim3 block(Threads);
  dim3 grid((unsigned)inner_blocks, (unsigned)outer_chunks, (unsigned)outer_per_chunk);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  max_reduce_dim_kernel<Threads, TileI, ChunkR><<<grid, block, 0, stream>>>(
      x_c.data_ptr<float>(),
      y.data_ptr<float>(),
      (int)outer,
      (int)R,
      (int)inner);
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "max_reduce_dim_kernel launch failed: ", cudaGetErrorString(err));
  return y;
}
"""

max_ext = load_inline(
    name="cute_max_reduce_ext",
    cpp_sources=max_cpp_decl,
    cuda_sources=max_cuda_src,
    functions=["max_reduce"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include"],
