  if (o >= outer) return;
  const int i = blockIdx.x * blockDim.x + threadIdx.x;
  if (i >= inner) return;
  const int seg = threadIdx.y;
  if (seg >= Segments) return;
  const int seg_len = (R + Segments - 1) / Segments;
  const int r0 = seg * seg_len;
  const int r1 = min(R, r0 + seg_len);
  const float* x_base = X + (int64_t)o * (int64_t)R * (int64_t)inner;
  float* p_base = P + ((int64_t)o * (int64_t)Segments + seg) * (int64_t)inner;
